import fs from 'fs';
import path from 'path';
import { Photo } from './data';

const PHOTOS_DATA_PATH = path.join(process.cwd(), 'data', 'photos.json');

// Ensure the data directory exists
const ensureDataDir = () => {
  const dir = path.dirname(PHOTOS_DATA_PATH);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
};

// Load photos from the JSON file
export const loadPhotosData = async (): Promise<Photo[]> => {
  try {
    ensureDataDir();
    if (!fs.existsSync(PHOTOS_DATA_PATH)) {
      return [];
    }
    const data = fs.readFileSync(PHOTOS_DATA_PATH, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    console.error('Error loading photos data:', error);
    return [];
  }
};

// Save photos to the JSON file
export const savePhotosData = async (photos: Photo[]): Promise<void> => {
  try {
    ensureDataDir();
    fs.writeFileSync(PHOTOS_DATA_PATH, JSON.stringify(photos, null, 2));
  } catch (error) {
    console.error('Error saving photos data:', error);
    throw error;
  }
};

// Add a new photo
export const addPhoto = async (photo: Photo): Promise<void> => {
  const photos = await loadPhotosData();
  photos.push(photo);
  await savePhotosData(photos);
};

// Update an existing photo
export const updatePhoto = async (photo: Photo): Promise<void> => {
  const photos = await loadPhotosData();
  const index = photos.findIndex(p => p.id === photo.id);
  if (index !== -1) {
    photos[index] = photo;
    await savePhotosData(photos);
  }
};

// Delete a photo
export const deletePhoto = async (photoId: string): Promise<void> => {
  const photos = await loadPhotosData();
  const filteredPhotos = photos.filter(p => p.id !== photoId);
  await savePhotosData(filteredPhotos);
}; 